import{b as s,O as a,g as n,j as i}from"./chunks/framework.DSt9LnBW.js";const c=JSON.parse('{"title":"Locust 还是 JMeter","description":"","frontmatter":{},"headers":[],"relativePath":"performance/locust/practice/locust-vs-jmeter/index.md","filePath":"性能测试/2.Locust/5.实战篇/26.Locust还是JMeter.md","lastUpdated":1789911840000}'),e={name:"performance/locust/practice/locust-vs-jmeter/index.md"};function r(o,t,p,d,l,h){return a(),n("div",null,[...t[0]||(t[0]=[i(`<h1 id="locust-还是-jmeter" tabindex="-1">Locust 还是 JMeter <a class="header-anchor" href="#locust-还是-jmeter" aria-label="Permalink to &quot;Locust 还是 JMeter&quot;">​</a></h1><blockquote><p>第 1 章<a href="/performance/locust/intro/what-is-locust/">Locust 是什么</a>里说过&quot;别急着站队，选型对比放在实战篇最后一章&quot;。现在你两种工具的路子都见过了，可以把这个话题讲透了。</p></blockquote><h2 id="先说结论" tabindex="-1">先说结论 <a class="header-anchor" href="#先说结论" aria-label="Permalink to &quot;先说结论&quot;">​</a></h2><p><strong>这不是&quot;哪个更好&quot;的问题，是&quot;你的场景适合哪个&quot;的问题。</strong> 两个工具都能压出正确的数字，选错了不会测不准，只会<strong>写起来很累、维护起来更累</strong>。</p><p>一句话决策：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Q1. 团队主力是开发，还是非开发？</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├─ 开发，会写代码</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   └─ Q2. 需要测多种协议吗？（JDBC / FTP / JMS）</span></span>
<span class="line"><span>│       ├─ 不需要，就是 HTTP 接口 ────────────→ Locust</span></span>
<span class="line"><span>│       └─ 需要 ──────────────────────────────→ JMeter</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└─ 非开发 / 测试为主</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    └─ Q3. 需要录制脚本吗？</span></span>
<span class="line"><span>        ├─ 需要 ────────────────────────────────→ JMeter</span></span>
<span class="line"><span>        └─ 不需要</span></span>
<span class="line"><span>            │</span></span>
<span class="line"><span>            └─ Q4. 已有 JMeter 体系吗？</span></span>
<span class="line"><span>                ├─ 已有 ────────────────────────→ JMeter</span></span>
<span class="line"><span>                └─ 没有 ────────────────────────→ Locust</span></span></code></pre></div><blockquote><p>四条问下来只落到两个出口：<strong>会写代码 + 只测 HTTP</strong>，或<strong>什么都不依赖、从零开始</strong> → Locust；<strong>要录制、要多种协议、已有 JMeter 资产</strong> → JMeter。</p></blockquote><h2 id="六个维度的硬对比" tabindex="-1">六个维度的硬对比 <a class="header-anchor" href="#六个维度的硬对比" aria-label="Permalink to &quot;六个维度的硬对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Locust</th><th>JMeter</th></tr></thead><tbody><tr><td><strong>脚本形式</strong></td><td>Python 代码（<code>.py</code>）</td><td>XML 文件（<code>.jmx</code>）+ GUI 编辑</td></tr><tr><td><strong>并发模型</strong></td><td>gevent 协程，单进程可上万用户</td><td>原生线程，1 用户 ≈ 1 线程</td></tr><tr><td><strong>资源开销</strong></td><td>低（一台笔记本可压出几千 RPS）</td><td>高（线程栈开销大，需更大内存）</td></tr><tr><td><strong>上手门槛</strong></td><td>要会 Python</td><td>会点鼠标就能跑通第一个脚本</td></tr><tr><td><strong>复杂业务逻辑</strong></td><td><strong>最强项</strong>——就是写代码，能接数据库、能调算法</td><td>靠元件组合，逻辑一复杂就难维护</td></tr><tr><td><strong>协议覆盖</strong></td><td>HTTP/HTTPS 开箱即用，其他协议靠插件或自己写 client</td><td><strong>最广</strong>——原生支持 JDBC/FTP/JMS/LDAP/TCP/SMTP 等</td></tr><tr><td><strong>脚本录制</strong></td><td>无内置。可用 <code>har2locust</code> 把浏览器 HAR 转成脚本</td><td>有 Test Script Recorder，点着鼠标录</td></tr><tr><td><strong>静态资源</strong></td><td><strong>不自动加载</strong> JS/CSS/图片</td><td>有 &quot;Retrieve All Embedded Resources&quot;</td></tr><tr><td><strong>报告</strong></td><td>HTML 报告 + CSV，自带 10 秒滑动窗口曲线</td><td>HTML Dashboard 报告</td></tr><tr><td><strong>分布式</strong></td><td><code>--master</code> / <code>--worker</code>，命令一行</td><td>master/slave，配置稍繁琐</td></tr><tr><td><strong>进 CI</strong></td><td>天然——<code>pip install locust</code> 加一行命令</td><td>需非 GUI 模式（<code>-n</code>）跑 <code>.jmx</code></td></tr><tr><td><strong>协作与评审</strong></td><td>代码可 diff、可 Code Review</td><td>XML 冲突难合，改动靠人描述</td></tr><tr><td><strong>生态与资料</strong></td><td>中等，官方文档全英文</td><td>极大，中文教程、插件、厂商支持都多</td></tr></tbody></table><h2 id="locust-真正强的场景" tabindex="-1">Locust 真正强的场景 <a class="header-anchor" href="#locust-真正强的场景" aria-label="Permalink to &quot;Locust 真正强的场景&quot;">​</a></h2><p><strong>1）业务链路复杂，需要写逻辑</strong></p><p>这是 Locust 的护城河。比如&quot;下单前要先查库存，库存不足就换一个商品，还要校验优惠券是否可用&quot;——在 Locust 里就是普通 Python：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">@task</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> create_order</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(self):</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pid </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pick_candidates():</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        stock </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> self</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.api_get(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/api/products/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pid</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).json()[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;stock&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stock </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">            self</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.api_post(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/api/orders&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">json</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;items&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [{</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;productId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: pid, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;quantity&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}]})</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">            return</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 全部无货，走降级分支</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    self</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.api_get(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/api/products?page=1&amp;pageSize=10&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>同样的逻辑在 JMeter 里要堆一堆 If Controller + JSON Extractor + 正则，改起来非常痛苦。</p><p><strong>2）要进 CI，要能被 CR</strong></p><p><code>locustfile.py</code> 是代码，能提 PR、能跑 lint、能 Code Review。JMeter 的 <code>.jmx</code> 是 XML，两个人同时改基本必冲突。</p><p><strong>3）压测机资源紧张</strong></p><p>协程模型让 Locust 用极少的 CPU/内存撑起高并发。第 16 章<a href="/performance/locust/scenarios/client-performance/">单机压不上去怎么办</a>里那张压测数据表就是这个优势的体现——单机十核能压出几千 RPS。</p><p><strong>4）团队是 Python 技术栈</strong></p><p>不用为了压测专门学一套 GUI 工具的思维方式，团队任何人上手都很快。</p><h2 id="jmeter-真正强的场景" tabindex="-1">JMeter 真正强的场景 <a class="header-anchor" href="#jmeter-真正强的场景" aria-label="Permalink to &quot;JMeter 真正强的场景&quot;">​</a></h2><p><strong>1）要测非 HTTP 协议</strong></p><p>JDBC 压数据库、FTP 传文件、JMS 压消息队列——这些 JMeter 原生支持，Locust 得自己造轮子。</p><p><strong>2）要模拟浏览器加载页面资源</strong></p><p>JMeter 的 &quot;Retrieve All Embedded Resources&quot; 会自动把 JS/CSS/图片一起请求，更接近真实页面访问。<strong>Locust 不会</strong>，要自己解析 HTML 再发请求。</p><p><strong>3）非开发人员主导</strong></p><p>测试团队里如果以不会写代码的同学为主，JMeter 的 GUI 是实打实的优势——录一遍、改改参数就能跑。</p><p><strong>4）已有成熟的 JMeter 体系</strong></p><p>这点最重要：<strong>已经沉淀了几十个 <code>.jmx</code> 脚本、CI 流水线、历史基线数据，就不要换。</strong> 迁移成本远大于收益，而且迁移过程本身会引入误差。</p><h2 id="一个常被忽略的事实" tabindex="-1">一个常被忽略的事实 <a class="header-anchor" href="#一个常被忽略的事实" aria-label="Permalink to &quot;一个常被忽略的事实&quot;">​</a></h2><p>这个文档站里同时有 <a href="/performance/jmeter/what-is-jmeter/">JMeter 教程</a>和 Locust 教程，不是为了让你二选一。</p><p>真实的性能测试团队里，两个工具常常<strong>并存</strong>：</p><table tabindex="0"><thead><tr><th>场景</th><th>用哪个</th></tr></thead><tbody><tr><td>日常接口回归压测、进 CI</td><td>Locust（脚本化、好维护）</td></tr><tr><td>复杂业务链路的全链路压测</td><td>Locust（逻辑能力）</td></tr><tr><td>数据库/中间件压测</td><td>JMeter（原生 JDBC/JMS）</td></tr><tr><td>需要录制的快速验证</td><td>JMeter（Recorder）</td></tr><tr><td>从浏览器行为快速生成脚本</td><td>JMeter 录制 → <code>har2locust</code> 转 Locust</td></tr></tbody></table><p>最后一行是个实用组合：<strong>用 JMeter 的录制能力抓下真实请求，再用 <code>har2locust</code> 转成 Locust 脚本</strong>，两边的长处都吃到。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 浏览器导出 HAR 文件后</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> har2locust</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">har2locust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> requests.har</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> locustfile.py</span></span></code></pre></div><p>转出来的脚本还要手工整理（去掉静态资源、补上断言、调整比例），但它能省掉&quot;逐个接口抄参数&quot;的体力活。</p><h2 id="迁移成本怎么估" tabindex="-1">迁移成本怎么估 <a class="header-anchor" href="#迁移成本怎么估" aria-label="Permalink to &quot;迁移成本怎么估&quot;">​</a></h2><p>如果你确实想从 JMeter 迁到 Locust，别一次性全迁。按这个顺序风险最低：</p><table tabindex="0"><thead><tr><th>阶段</th><th>做什么</th><th>风险</th></tr></thead><tbody><tr><td>1）试点</td><td>挑 1 个最简单的只读接口场景，用 Locust 重写</td><td>低</td></tr><tr><td>2）对拉</td><td>同一个场景两个工具各跑一次，<strong>对比 RPS 和 P95 是否量级一致</strong></td><td>低</td></tr><tr><td>3）扩展</td><td>复杂链路迁 Locust，非 HTTP 协议留在 JMeter</td><td>中</td></tr><tr><td>4）切换 CI</td><td>新场景默认用 Locust，老脚本保留不动</td><td>中</td></tr></tbody></table><p><strong>阶段 2 是关键</strong>：如果两个工具压出来的数字差很多，说明其中有人的配置有问题（超时、连接复用、断言口径），先把口径对齐再往下走。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><strong>不是二选一</strong>：看场景、看团队、看存量资产</li><li><strong>选 Locust</strong>：HTTP 接口为主、业务逻辑复杂、要进 CI、要 Code Review、团队是 Python 栈</li><li><strong>选 JMeter</strong>：要测 JDBC/FTP/JMS 等非 HTTP 协议、要模拟页面静态资源、非开发主导、已有成熟体系</li><li><strong>已投入的体系别轻易换</strong>——迁移成本通常大于收益</li><li><strong>可以混用</strong>：JMeter 录制 + <code>har2locust</code> 转换，是最高效的取长补短</li><li><strong>迁移要分阶段</strong>，并且<strong>先对拉验证两个工具的数字量级一致</strong>，再扩大范围</li></ul><hr><h2 id="实战篇收尾" tabindex="-1">实战篇收尾 <a class="header-anchor" href="#实战篇收尾" aria-label="Permalink to &quot;实战篇收尾&quot;">​</a></h2><p>到这里，实战篇结束了。回看整条主线，顺序和第 1 章<a href="/performance/locust/intro/what-is-locust/">Locust 是什么</a>的规划一致：</p><table tabindex="0"><thead><tr><th>篇章</th><th>你会得到什么</th></tr></thead><tbody><tr><td><strong>入门篇</strong></td><td>装好环境、跑通脚本、看懂 Web UI 和命令行</td></tr><tr><td><strong>核心篇</strong></td><td>独立写脚本：用户、任务、等待时间、请求、断言、事件钩子</td></tr><tr><td><strong>场景篇</strong></td><td>设计负载形状、判断长压测劣化、分布式扩容、突破单机瓶颈</td></tr><tr><td><strong>进阶篇</strong></td><td>测试数据、流式接口、pytest 集成、调试排错、监控与 CI</td></tr><tr><td><strong>实战篇</strong></td><td>交付一次完整压测：登录态、真实比例、阶梯找拐点、写报告</td></tr></tbody></table><p><strong>进阶篇排在实战篇之前是有意为之</strong>：里面那些工程能力——造测试数据、调试排错、压测时监控服务、把脚本接进 CI——正是本章开头说的&quot;能交给团队、能重复跑&quot;所依赖的东西。先把工具箱备齐，再上战场。</p><p><strong>五篇合起来，你要交付的其实就一句话：</strong></p><blockquote><p>「这个系统在 XX 并发下，P95 是 XX ms、失败率 XX%，拐点在 XX，瓶颈是 XX，建议容量按 XX 配。」</p></blockquote><p>剩下的都是支撑这句话的证据。</p><p>实战篇是主线的收束。再往后是 <strong>大模型压测篇</strong>——压 AI 接口关心的东西完全不同：TTFT（首 token 时间）、tokens/s、429 限流、空响应，流式和非流式也要分开测。从第 27 章<a href="/performance/locust/llm/basics/">大模型压测的特殊之处</a>开始。</p>`,51)])])}const g=s(e,[["render",r]]);export{c as __pageData,g as default};
